import{_ as s,l as r,o as e,c as n,v as l,p as i,x as t,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Claude Fable 5","description":"","frontmatter":{"title":"Claude Fable 5","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/claude-fable-5.md","filePath":"llm/claude-fable-5.md","lastUpdated":1789023840000}'),u={name:"llm/claude-fable-5.md"};function c(b,a,E,F,A,m){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="claude-fable-5" tabindex="-1">Claude Fable 5 <a class="header-anchor" href="#claude-fable-5" aria-label="Permalink to &quot;Claude Fable 5&quot;">​</a></h1><div class="epigraph"><p>今天我们发布 Claude Fable 5：一个已做成可一般使用的 Mythos 级模型。能力超过我们以往任何一般可用模型；任务越长越复杂，领先越大。</p><footer>—— Anthropic，Claude Fable 5 and Claude Mythos 5（2026-06-09）</footer></div><p><strong>Claude Fable 5</strong> 是 Anthropic 5 代里面向一般可用的最高能力档，API <code>claude-fable-5</code>，价 <strong>$10 / $50</strong> 每百万 token。同一底层权重、在部分领域撤掉防护的版本叫 <strong>Claude Mythos 5</strong>，经 Project Glasswing 与后续可信访问发放，不面向全体开发者。命名脚注：Fable 来自拉丁语 fabula（被讲述的），与希腊语 mythos 相对——<strong>区分二者的是防护，不是两套预训练</strong>。本篇只写 2026-06-09 研究博文、产品页与 6 月中旬曾暂停、7 月 1 日恢复的公开状态，<strong>不编参数量、不写攻击细节</strong>。9 月的 Fable 5.1 是后续快照，另文处理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Mythos Preview 已在 2026 年 4 月只给网络防御与关键软件基础设施。Anthropic 当时说：希望在防护够强时把 Mythos 级能力给全体用户。Fable 5 就是这条路径的一般可用面：能力按官方说法在软件工程、知识工作、视觉、科研等几乎所有测试上 SOTA，但网络、生物/化学、蒸馏三类请求会被分类器改道到当时的次强公开模型 <strong>Opus 4.8</strong>（Opus 5 发布后，产品页把部分生物回落改到 Opus 5）。若没有系统层，官方判断存在严重滥用 uplift。</p><p>产品约束包括：分类器偏保守，早期数据称平均不到 5% 的会话触发，但会误伤良性请求；订阅计划曾分阶段限额（6 月 9–22 含在 Pro/Max/Team/Enterprise，6 月 23 日起改用量额度）。6 月 12 日公开暂停 Fable/Mythos 访问，7 月 1 日宣布恢复——写「一直 GA」与变更日志不符。</p><h3 id="fable-另一个-opus-尺寸" tabindex="-1">Fable ≠ 另一个 Opus 尺寸 <a class="header-anchor" href="#fable-另一个-opus-尺寸" aria-label="Permalink to &quot;Fable ≠ 另一个 Opus 尺寸&quot;">​</a></h3><p>Opus 5 后来自称「半价接近 Fable」。那是 7 月的定价叙事。6 月文里 Fable 的比较对象是 Opus 4.8 与其他前沿模型。不要把 Fable 写成 Opus 4.6 的改名。Mythos-class 是 Opus 之上的能力层；Preview → Fable/Mythos 5 是该层的第一次一般可用拆分。</p><p><span class="marginnote">价目 $10/$50 低于 Mythos Preview（官方称不到一半）。Prompt cache 仍有 90% 输入折扣。30 天数据保留适用于 Mythos 级流量，用于安全、不用于训练——见博文「新保留政策」节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开方法是评测故事 + 分类器回落。软件工程：Stripe 在约 5000 万行 Ruby 库上「一天完成原需团队两个月」的迁移，是客户存在性案例。Cognition FrontierCode：高生产标准下 Fable 即使 medium effort 也最高。视觉：从截图重建 web 应用；宝可梦 FireRed 只用原始画面、无地图辅助通关——官方用来对比早先 Claude 需要复杂 harness。记忆：Slay the Spire 上文件记忆带来的提升约是 Opus 4.8 的三倍，进终章频率约三倍。这些是演示协议，不是公开的百万 token 窗口规格表。</p><p>Mythos 5 侧（同一权重、防护更少）给出科研叙述：内部蛋白设计在工具加持、无人工协助时「匹配或超过熟练操作者」；14 个靶点中 9 个进入后续候选；分子生物假设盲测约 80% 偏好相对 Opus 档；基因组学上约一周偏自主工作，训练的小模型在跨物种细胞对齐上优于一篇 Science 近作且小 100 倍——官方称将另发文。这些是 Mythos 可信访问语境，<strong>不能</strong>当成 Fable 网页聊天的默认能力：Fable 会把多数生物请求回落。</p>',12)),(e(),i(p,null,{default:t(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20CLF%5B%22%E5%88%86%E7%B1%BB%E5%99%A8%EF%BC%9A%E7%BD%91%E7%BB%9C%20%2F%20%E7%94%9F%E7%89%A9%E5%8C%96%E5%AD%A6%20%2F%20%E8%92%B8%E9%A6%8F%22%5D%0A%20%20CLF%20--%3E%7C%E6%9C%AA%E5%91%BD%E4%B8%AD%20%E2%89%8895%25%20%E4%BC%9A%E8%AF%9D%7C%20F%5B%22Fable%205%20%3D%20Mythos%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20CLF%20--%3E%7C%E5%91%BD%E4%B8%AD%7C%20O%5B%22%E5%9B%9E%E8%90%BD%20Opus%204.8%EF%BC%88%E5%90%8E%E6%9C%89%E7%94%9F%E7%89%A9%E6%94%B9%20Opus%205%EF%BC%89%22%5D%0A%20%20M%5B%22Mythos%205%20%E5%8F%AF%E4%BF%A1%E8%AE%BF%E9%97%AE%22%5D%20--%3E%20LIFT%5B%22%E9%83%A8%E5%88%86%E9%98%B2%E6%8A%A4%E8%A7%A3%E9%99%A4%22%5D%0A%20%20F%20--%3E%20RET%5B%22Mythos%20%E7%BA%A7%2030%20%E5%A4%A9%E4%BF%9D%E7%95%99%22%5D%0A%20%20M%20--%3E%20RET%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="分类器覆盖面-政策层" tabindex="-1">分类器覆盖面（政策层） <a class="header-anchor" href="#分类器覆盖面-政策层" aria-label="Permalink to &quot;分类器覆盖面（政策层）&quot;">​</a></h3><ol><li>网络：发现与利用漏洞、更宽的进攻性代理任务；评测图在「拦下而非回落」模式下显示进攻任务无进展。外部红队与赏金：逾 1000 小时无通用越狱；UK AISI 在短窗口内朝通用越狱有进展。2. 生物与化学：不再只拦窄带生物武器问句；因 AAV 外壳组装预测等双用途任务上 Mythos 级可超过专用蛋白模型，初期对多数生物/化学请求回落。3. 蒸馏：大规模抽取能力去训竞争模型的流量回落。用户会看到回落通知。对齐审计：Mythos 5 失配率低、与 Opus 4.8 相似，故 Fable 同类。</li></ol><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Fable 的机制是 <strong>Mythos 级模型 + 外部分类器门面</strong>。一般会话里两者分数应当接近（&gt;95% 无回落）。一旦话题进入双用途，用户实际在打 Opus。评测若关掉分类器，测的是裸 Mythos 能力，与生产 Fable 不是同一系统。30 天保留被写成检测跨请求攻击与降误伤的数据面，不是训练语料。</p><p><span class="marginnote">宝可梦、Factorio、CAD、流体可视化是官方演示视频级证据，证明长程视觉与工具环，不是标准 LLM 榜。Finance / CursorBench / FrontierBench 的「最高」来自客户或合作评测，须标出处。</span></p><h3 id="和-opus-5、和-5-1" tabindex="-1">和 Opus 5、和 5.1 <a class="header-anchor" href="#和-opus-5、和-5-1" aria-label="Permalink to &quot;和 Opus 5、和 5.1&quot;">​</a></h3><p>Opus 5（7 月）把日常旗舰拉近 Fable，并收窄网络拦截、承接部分生物回落。Fable 5.1 / Mythos 5.1（9 月博文）是同名线的后续，带更新的可信访问（CVP / LSVP）。本篇停在 5.0 发布文。不要把 5.1 的 AutomationBench 句抄进 5.0。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="暂停窗口属于公开状态的一部分" tabindex="-1">暂停窗口属于公开状态的一部分 <a class="header-anchor" href="#暂停窗口属于公开状态的一部分" aria-label="Permalink to &quot;暂停窗口属于公开状态的一部分&quot;">​</a></h3><p>6 月 12 日官方宣布暂停 Fable 5 与 Mythos 5 访问，7 月 1 日恢复。产品页后来写「Access to Claude Fable 5 has been restored」。任何「2026 年 6 月起连续 GA」的时间线都少了这两周。原因页应指向当时状态博文，本篇不猜测内部事故。容量分期（先含在订阅、再改额度）说明即使恢复后，座位计划也不等于无限 Fable。</p><p>无参数、无架构。分类器误伤是明确代价。Mythos 5 的蛋白/基因组故事禁止写进「Fable 默认能做湿实验」。越狱「尚无通用」不是定理；官方自己写不可能完全消除。蒸馏拦截会误伤研究抽取。订阅是否含 Fable 以当时容量公告为准。</p><p>出处：Anthropic，<em>Claude Fable 5 and Claude Mythos 5</em>，2026-06-09（含 6/12 暂停、7/1 恢复更新）；产品页 anthropic.com/claude/fable。参数量未公开。</p><p><span class="marginnote">脚注定义通用越狱：能让用户像防护不存在一样交互的提示/脚本/harness。短任务上的内部红队图（含「远程加密文件」一类简单项）不代表真实进攻任务已突破。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Fable 5 是 2026-06-09 一般可用的 Mythos 级模型，$10/$50，id <code>claude-fable-5</code>。</li><li>Mythos 5 是同权、部分防护解除的可信访问版本。</li><li>生产合同是分类器回落到 Opus；多数会话不触发。</li><li>演示强调超长程编码、视觉与（仅 Mythos）科研；无公开参数表。</li><li>出处：上述官方博文与产品页。不编架构、不写攻击方法。</li></ul>',15))])}const f=s(u,[["render",c]]);export{C as __pageData,f as default};
